-- ============================================================
-- 循環杯門市完整資料匯入腳本 (Self-contained / 免 ETL)
-- 資料庫: dashboard
-- ============================================================
--
-- 說明：
--   本腳本包含 ETL 已處理完畢的所有資料（含 geocoding 結果），
--   協作者可直接執行此腳本，無需執行 Python ETL 腳本或持有
--   Mapbox API Token。
--
--   匯入內容：
--     • public.reusable_cup_stores  (1770 筆門市點位，含 lng/lat)
--     • public.reusable_cup_stats   (38 筆各區統計)
--
-- 執行方式：
--   docker cp db-sample-data/add_reusable_cup_data.sql postgres-data:/tmp/
--   docker exec postgres-data psql -U postgres -d dashboard \
--     -f /tmp/add_reusable_cup_data.sql
--
-- 前置條件：PostGIS extension（腳本內已自動建立）
-- ============================================================

CREATE EXTENSION IF NOT EXISTS postgis;

--
-- PostgreSQL database dump
--

-- Dumped from database version 16.4
-- Dumped by pg_dump version 16.4

SET statement_timeout = 0;
SET lock_timeout = 0;
