SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: reusable_cup_stats; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reusable_cup_stats (
    district character varying(50),
    count integer,
    city character varying(50)
);


--
-- Name: reusable_cup_stores; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reusable_cup_stores (
    brand character varying(100),
    city character varying(50),
    store_name character varying(200),
    address character varying(300),
    phone character varying(50),
    lng double precision,
    lat double precision,
    wkb_geometry public.geometry(Point,4326)
);


--
-- Data for Name: reusable_cup_stats; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: reusable_cup_stores; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- PostgreSQL database dump complete
--


-- ── 更新 wkb_geometry 欄位（由 lng/lat 計算）────────────────────────────────
UPDATE public.reusable_cup_stores
SET wkb_geometry = ST_SetSRID(ST_MakePoint(lng, lat), 4326)
WHERE lng IS NOT NULL AND lat IS NOT NULL;

-- ── 驗證 ──────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  cnt_stores INTEGER;
  cnt_stats  INTEGER;
BEGIN
  SELECT COUNT(*) INTO cnt_stores FROM public.reusable_cup_stores;
  SELECT COUNT(*) INTO cnt_stats  FROM public.reusable_cup_stats;
  RAISE NOTICE '✓ reusable_cup_stores: % 筆', cnt_stores;
  RAISE NOTICE '✓ reusable_cup_stats:  % 筆', cnt_stats;
END $$;